    22→final class NSEUserSession: NSEUserSessionProtocol {
    23→    private let sessionDirectories: SessionDirectories
    24→    private let appSettings: CommonSettingsProtocol
    25→    private let baseClient: Client
    26→    private let notificationClient: NotificationClient
    27→    private let userID: String
    28→    private(set) lazy var mediaProvider: MediaProviderProtocol = MediaProvider(mediaLoader: MediaLoader(client: baseClient),
    29→                                                                               imageCache: .onlyOnDisk,
    30→                                                                               homeserverReachabilityPublisher: nil)
    31→    private let delegateHandle: TaskHandle?
    32→    
    33→    var mediaPreviewVisibility: MediaPreviews {
    34→        get async {
    35→            do {
    36→                return try await baseClient.getMediaPreviewDisplayPolicy() ?? .on
    37→            } catch {
    38→                MXLog.error("Failed to get media preview visibility, defaulting to on. Error: \(error)")
    39→                return .on
    40→            }
    41→        }
    42→    }
    43→    
    44→    var inviteAvatarsVisibility: InviteAvatars {
    45→        get async {
    46→            do {
    47→                return try await baseClient.getInviteAvatarsDisplayPolicy() ?? .on
    48→            } catch {
    49→                MXLog.error("Failed to get invite avatars visibility, defaulting to on. Error: \(error)")
    50→                return .on
    51→            }
    52→        }
    53→    }
    54→    
    55→    var threadsEnabled: Bool {
    56→        appSettings.threadsEnabled
    57→    }
    58→
    59→    init(credentials: KeychainCredentials,
    60→         roomID: String,
    61→         clientSessionDelegate: ClientSessionDelegate,
    62→         appHooks: AppHooks,
    63→         appSettings: CommonSettingsProtocol) async throws {
    64→        sessionDirectories = credentials.restorationToken.sessionDirectories
    65→        userID = credentials.userID
    66→        self.appSettings = appSettings
    67→        
    68→        let homeserverURL = credentials.restorationToken.session.homeserverUrl
    69→        let clientBuilder = ClientBuilder
    70→            .baseBuilder(setupEncryption: false,
    71→                         httpProxy: URL(string: homeserverURL)?.globalProxy,
    72→                         slidingSync: .restored,
    73→                         sessionDelegate: clientSessionDelegate,
    74→                         appHooks: appHooks,
    75→                         enableOnlySignedDeviceIsolationMode: appSettings.enableOnlySignedDeviceIsolationMode,
    76→                         enableKeyShareOnInvite: appSettings.enableKeyShareOnInvite,
    77→                         requestTimeout: 15000,
    78→                         maxRequestRetryTime: 5000,
    79→                         threadsEnabled: appSettings.threadsEnabled)
    80→            .systemIsMemoryConstrained()
    81→            .sqliteStore(config: .init(dataPath: credentials.restorationToken.sessionDirectories.dataPath,
    82→                                       cachePath: credentials.restorationToken.sessionDirectories.cachePath)
    83→                    .passphrase(passphrase: credentials.restorationToken.passphrase))
    84→            .username(username: credentials.userID)
    85→            .homeserverUrl(url: homeserverURL)
    86→        
    87→        baseClient = try await clientBuilder.build()
    88→        delegateHandle = try baseClient.setDelegate(delegate: ClientDelegateWrapper())
    89→        
    90→        try await baseClient.restoreSessionWith(session: credentials.restorationToken.session,
    91→                                                roomLoadSettings: .one(roomId: roomID))
    92→        
    93→        notificationClient = try await baseClient.notificationClient(processSetup: .multipleProcesses)
    94→    }
    95→    
    96→    func notificationItemProxy(roomID: String, eventID: String) async -> NotificationItemProxyProtocol? {
    97→        do {
    98→            let notificationStatus = try await notificationClient.getNotification(roomId: roomID, eventId: eventID)
    99→                
   100→            switch notificationStatus {
   101→            case .event(let notification):
   102→                return NotificationItemProxy(notificationItem: notification,
   103→                                             eventID: eventID,
   104→                                             receiverID: userID,
   105→                                             roomID: roomID)
   106→            case .eventNotFound:
   107→                MXLog.error("Notification event not found - roomID: \(roomID) eventID: \(eventID)")
   108→                return nil
   109→            case .eventFilteredOut:
   110→                MXLog.warning("Notification event filtered out - roomID: \(roomID) eventID: \(eventID)")
   111→                return nil
   112→            }
   113→        } catch {
   114→            MXLog.error("Could not get notification's content creating an empty notification instead, error: \(error)")
   115→            return EmptyNotificationItemProxy(eventID: eventID, roomID: roomID, receiverID: userID)
   116→        }
   117→    }
   118→    
   119→    func roomForIdentifier(_ roomID: String) -> Room? {
   120→        do {
   121→            return try notificationClient.getRoom(roomId: roomID)
   122→        } catch {
   123→            MXLog.error("Failed retrieving room with error: \(error)")
   124→            return nil
   125→        }
   126→    }
   127→    
   128→    deinit {
   129→        delegateHandle?.cancel()
   130→    }
   131→}
   132→
   133→private final class ClientDelegateWrapper: ClientDelegate {
   134→    // MARK: - ClientDelegate
   135→
   136→    func didReceiveAuthError(isSoftLogout: Bool) {
   137→        MXLog.error("Received authentication error, the NSE can't handle this.")
   138→    }
   139→    
   140→    func didRefreshTokens() {
   141→        MXLog.info("Delegating session updates to the ClientSessionDelegate.")
   142→    }
   143→}
