    78→        if let roomAvatarURLString = notificationItem.roomInfo.avatarUrl,
    79→           let roomAvatarURL = URL(string: roomAvatarURLString) {
    80→            return try? MediaSourceProxy(url: roomAvatarURL, mimeType: nil)
    81→        }
    82→        return nil
    83→    }
    84→    
    85→    var threadRootEventID: String? {
