     9→import Foundation
    10→
    11→struct SessionDirectories: Hashable, Codable {
    12→    let dataDirectory: URL
    13→    let cacheDirectory: URL
    14→    
    15→    var dataPath: String { dataDirectory.path(percentEncoded: false) }
    16→    var cachePath: String { cacheDirectory.path(percentEncoded: false) }
    17→    
    18→    // MARK: Data Management
    19→    
    20→    /// Removes the directories from disk if they have been created.
    21→    func delete() {
    22→        do {
    23→            if FileManager.default.directoryExists(at: dataDirectory) {
    24→                try FileManager.default.removeItem(at: dataDirectory)
    25→            }
    26→        } catch {
    27→            MXLog.failure("Failed deleting the session data: \(error)")
    28→        }
    29→        do {
    30→            if FileManager.default.directoryExists(at: cacheDirectory) {
    31→                try FileManager.default.removeItem(at: cacheDirectory)
    32→            }
    33→        } catch {
    34→            MXLog.failure("Failed deleting the session caches: \(error)")
    35→        }
    36→    }
    37→    
    38→    /// Deletes the Rust state store and event cache data, leaving the crypto store and both
    39→    /// session directories in place along with any other data that may have been written in them.
    40→    func deleteTransientUserData() {
    41→        do {
    42→            let prefix = "matrix-sdk-state"
    43→            try deleteFiles(at: dataDirectory, with: prefix)
    44→        } catch {
    45→            MXLog.failure("Failed clearing state store: \(error)")
    46→        }
    47→        do {
    48→            let prefix = "matrix-sdk-event-cache"
    49→            try deleteFiles(at: cacheDirectory, with: prefix)
    50→        } catch {
    51→            MXLog.failure("Failed clearing event cache store: \(error)")
    52→        }
    53→    }
    54→    
    55→    /// Check that mission critical files (the crypto db) are still in the right place when restoring a session
    56→    /// iOS might decide to move the app with its user defaults and keychain but without
    57→    /// some of the files stored in the shared container e.g. after a device transfer, offloading etc.
    58→    /// If that happens we should fail the session restoration.
    59→    func isNonTransientUserDataValid() -> Bool {
    60→        FileManager.default.fileExists(atPath: dataPath.appending("/matrix-sdk-crypto.sqlite3"))
    61→    }
    62→    
    63→    private func deleteFiles(at url: URL, with prefix: String) throws {
    64→        let sessionDirectoryContents = try FileManager.default.contentsOfDirectory(at: url, includingPropertiesForKeys: nil)
    65→        for url in sessionDirectoryContents where url.lastPathComponent.hasPrefix(prefix) {
    66→            try FileManager.default.removeItem(at: url)
    67→        }
    68→    }
    69→}
    70→
    71→extension SessionDirectories {
    72→    /// Creates a fresh set of session directories for a new user.
    73→    init() {
    74→        let sessionDirectoryName = UUID().uuidString
    75→        dataDirectory = .sessionsBaseDirectory.appending(component: sessionDirectoryName)
    76→        cacheDirectory = .sessionCachesBaseDirectory.appending(component: sessionDirectoryName)
    77→    }
    78→    
    79→    /// Creates the session directories for a user who has a single session directory stored without a separate caches directory.
    80→    init(dataDirectory: URL) {
    81→        self.dataDirectory = dataDirectory
    82→        cacheDirectory = .sessionCachesBaseDirectory.appending(component: dataDirectory.lastPathComponent)
    83→    }
    84→}
