    61→    func requestAuthorization() {
    62→        guard appSettings.enableNotifications, !userSession.isNil else { return }
    63→        Task {
    64→            do {
    65→                let permissionGranted = try await notificationCenter.requestAuthorization(options: [.alert, .sound, .badge])
    66→                MXLog.info("Permission granted: \(permissionGranted)")
    67→                await MainActor.run {
    68→                    if permissionGranted {
    69→                        self.delegate?.registerForRemoteNotifications()
    70→                    }
    71→                }
    72→            } catch {
    73→                MXLog.error("Request authorization failed: \(error)")
    74→            }
    75→        }
    76→    }
