   194→    private func enableNotifications(_ enable: Bool) {
   195→        guard notificationsEnabled != enable else { return }
   196→        notificationsEnabled = enable
   197→        MXLog.info("App setting 'enableNotifications' changed to '\(enable)'")
   198→        if enable {
   199→            requestAuthorization()
   200→        } else {
   201→            delegate?.unregisterForRemoteNotifications()
   202→        }
   203→    }
   204→}
